{"path":"/root/solve.py","content":"#!/usr/bin/env python3
"""Generate VaxCrate 6-day vs 12-day financial analysis artifacts."""

import csv
import json
from pathlib import Path

ROOT = Path('/root')


def money(value):
    """Round currency values to exactly two decimal places as a float."""
    return round(float(value) + 1e-9, 2)


def read_csv_dict(path):
    with path.open(newline='', encoding='utf-8') as f:
        return list(csv.DictReader(f))


def nonblank(value):
    return value is not None and str(value).strip() != ''


def load_campaigns(manifest_path):
    with manifest_path.open(encoding='utf-8') as f:
        manifest = json.load(f)

    campaigns = []
    for region in manifest.get('regions', []):
        for campaign in region.get('campaigns', []):
            campaigns.append(campaign)
    return campaigns


def latest_active_billing(campaign, billing_rows):
    labels = {campaign['campaign_name'], *campaign.get('alias_labels', [])}
    matches = [
        row for row in billing_rows
        if row.get('campaign_label') in labels and row.get('status') == 'active'
    ]
    if not matches:
        raise ValueError(f"No active billing row found for {campaign['campaign_id']}")
    return max(matches, key=lambda row: row.get('cycle_tag', ''))


def resolved_active_clinics(campaign, override_rows):
    valid_rows = []
    for row in override_rows:
        if row.get('campaign_id') != campaign['campaign_id']:
            continue
        if row.get('state') != 'approved':
            continue
        if not nonblank(row.get('revision')) or not nonblank(row.get('active_clinics')):
            continue
        valid_rows.append(row)

    if not valid_rows:
        return int(campaign['default_active_clinics'])

    selected = max(valid_rows, key=lambda row: int(float(row['revision'])))
    active = float(selected['active_clinics'])
    return int(active) if active.is_integer() else active


def main():
    campaigns = load_campaigns(ROOT / 'campaign_manifest.json')
    crate_costs = {
        row['crate_tier']: float(row['crate_cost_usd'])
        for row in read_csv_dict(ROOT / 'crate_cost.csv')
    }
    billing_rows = read_csv_dict(ROOT / 'billing.csv')
    override_rows = read_csv_dict(ROOT / 'location_overrides.csv')
    suspension_rows = read_csv_dict(ROOT / 'suspensions.csv')

    held_campaign_ids = {
        row['campaign_id'] for row in suspension_rows
        if row.get('suspension_status') == 'hold'
    }

    retained = [
        campaign for campaign in campaigns
        if campaign.get('analysis_flag') == 'review'
        and campaign.get('campaign_id') not in held_campaign_ids
    ]

    output_campaigns = []
    for campaign in retained:
        billing = latest_active_billing(campaign, billing_rows)
        active_clinics = resolved_active_clinics(campaign, override_rows)
        payment = float(billing['payment_per_dispatch_per_clinic_usd'])
        drug_cost = float(campaign['drug_cost_per_1000_doses_usd'])
        doses_per_day = float(campaign['doses_per_day'])
        crate_tier = campaign['crate_tier']
        crate_cost = float(crate_costs[crate_tier])

        annual_revenue_6 = payment * active_clinics * 60
        annual_drug_cost_6 = drug_cost * active_clinics * doses_per_day * 6 * 60 / 1000
        annual_crate_cost_6 = crate_cost * 60
        annual_margin_6 = annual_revenue_6 - annual_drug_cost_6 - annual_crate_cost_6

        annual_revenue_12 = payment * active_clinics * 30
        annual_drug_cost_12 = drug_cost * active_clinics * doses_per_day * 12 * 30 / 1000
        annual_crate_cost_12 = crate_cost * 30
        annual_margin_12 = annual_revenue_12 - annual_drug_cost_12 - annual_crate_cost_12

        output_campaigns.append({
            'campaign_id': campaign['campaign_id'],
            'campaign_name': campaign['campaign_name'],
            'active_clinics': active_clinics,
            'crate_tier': crate_tier,
            'crate_cost_usd': money(crate_cost),
            'payment_per_dispatch_per_clinic_usd': money(payment),
            'annual_revenue_6_usd': money(annual_revenue_6),
            'annual_drug_cost_6_usd': money(annual_drug_cost_6),
            'annual_crate_cost_6_usd': money(annual_crate_cost_6),
            'annual_margin_6_usd': money(annual_margin_6),
            'annual_revenue_12_usd': money(annual_revenue_12),
            'annual_drug_cost_12_usd': money(annual_drug_cost_12),
            'annual_crate_cost_12_usd': money(annual_crate_cost_12),
            'annual_margin_12_usd': money(annual_margin_12),
            'difference_usd': money(annual_margin_12 - annual_margin_6),
        })

    output_campaigns.sort(key=lambda item: item['campaign_id'])

    total_margin_6 = money(sum(item['annual_margin_6_usd'] for item in output_campaigns))
    total_margin_12 = money(sum(item['annual_margin_12_usd'] for item in output_campaigns))
    total_difference = money(sum(item['difference_usd'] for item in output_campaigns))
    absolute_difference = money(abs(total_difference))
    threshold = 11000
    decision = 'move_to_12_day' if absolute_difference < threshold else 'keep_6_day'

    result = {
        'campaigns': output_campaigns,
        'totals': {
            'total_margin_6_usd': total_margin_6,
            'total_margin_12_usd': total_margin_12,
            'total_difference_usd': total_difference,
            'absolute_difference_usd': absolute_difference,
        },
        'decision': decision,
        'assumptions': {
            'six_day_model': {
                'days_per_dispatch': 6,
                'dispatches_per_year': 60,
            },
            'twelve_day_model': {
                'days_per_dispatch': 12,
                'dispatches_per_year': 30,
            },
            'decision_threshold_usd': threshold,
            'annual_crate_cost_formula': 'crate_cost_usd * dispatches_per_year',
        },
        'justification': (
            f"Absolute difference is ${absolute_difference:,.2f}, compared with the "
            f"${threshold:,.2f} threshold; decision is {decision}."
        ),
    }

    with (ROOT / 'vaxcrate_analysis.json').open('w', encoding='utf-8') as f:
        json.dump(result, f, indent=2)
        f.write('\n')

    summary_lines = [
        '# VaxCrate Dispatch Model Summary',
        f'Total 6-day margin (USD): ${total_margin_6:,.2f}',
        f'Total 12-day margin (USD): ${total_margin_12:,.2f}',
        f'Absolute difference (USD): ${absolute_difference:,.2f}',
        f'Final decision: {decision}',
    ]
    (ROOT / 'vaxcrate_summary.md').write_text('\n'.join(summary_lines) + '\n', encoding='utf-8')


if __name__ == '__main__':
    main()
","cross_profile":false}

